const nextInvoiceNumber = `-- name: NextInvoiceNumber :one
INSERT INTO invoice_counters (year, last) VALUES ($1, 1)
ON CONFLICT (year) DO UPDATE SET last = invoice_counters.last + 1
RETURNING last
`

// Moves the year's counter within the caller's transaction, so numbers have
// no gaps.
func (q *Queries) NextInvoiceNumber(ctx context.Context, year int32) (int32, error) {
	row := q.db.QueryRow(ctx, nextInvoiceNumber, year)
	var last int32
	err := row.Scan(&last)
	return last, err
}

